from pathlib import Path
import math,json,hashlib,time
B=Path(__file__).resolve().parent;p=B/'analyze_wmma_dot_float_r1.py';s={'__file__':str(p)}
exec(p.read_text().split('started=time.monotonic()')[0],s)
left,right,initial,trace,half,half_e,bits,value=[s[n] for n in ('left','right','initial','trace','half','half_e','bits','value')]
def predict(a,b,craw,mode):
    def exponent(h):
        return half_e(h) if mode==0 else max((h>>10)&31,1)-15 if mode==1 else ((h>>10)&31)-15
    ep=max(exponent(a[i])+exponent(b[i]) if (a[i]&0x7fff) and (b[i]&0x7fff) else -126 for i in range(2))
    c=value(craw);ce=((craw>>23)&255)-127 if c else -126;e=max(ep,ce-2);q=math.ldexp(1.0,e-24)
    total=math.trunc(c/q)+2*(craw>>31)
    for av,bv in zip(a,b):
        magnitude=math.trunc(abs(half(av)*half(bv))/q);total+=-(magnitude+1) if (av^bv)&0x8000 else magnitude
    raw=bits(total*q)
    return 0 if (raw&0x7fffffff)<0x800000 else raw
started=time.monotonic();counts=[[0]*8 for _ in range(3)];examples={m:[] for m in range(3)}
for cell in range(131072):
    tile,pos=divmod(cell,256);row,col=divmod(pos,16);family=cell//16384
    a=left[tile*256+row*16:tile*256+row*16+16];b=right[tile*256+col*16:tile*256+col*16+16]
    for step in range(8):
        index=cell*8+step;craw=trace[index-1] if step else initial[cell]
        for mode in range(3):
            got=predict(a[2*step:2*step+2],b[2*step:2*step+2],craw,mode)
            if got!=trace[index]:
                counts[mode][family]+=1
                if len(examples[mode])<8:examples[mode].append(dict(cell=cell,step=step,a=list(a[2*step:2*step+2]),b=list(b[2*step:2*step+2]),carry_bits=craw,carry=value(craw),native_bits=trace[index],native=value(trace[index]),prediction_bits=got,prediction=value(got)))
print(json.dumps(dict(actual_prefix_mismatches=counts,examples=examples),indent=2),flush=True)
best=min(range(3),key=lambda m:sum(counts[m]));recursive_bad=0;end_bad=0
for cell in range(131072):
    tile,pos=divmod(cell,256);row,col=divmod(pos,16);a=left[tile*256+row*16:tile*256+row*16+16];b=right[tile*256+col*16:tile*256+col*16+16];carry=initial[cell]
    for step in range(8):
        carry=predict(a[2*step:2*step+2],b[2*step:2*step+2],carry,best);recursive_bad+=carry!=trace[cell*8+step]
    end_bad+=carry!=trace[cell*8+7]
record=dict(kind='signed_zero_and_subnormal_dot2_hypothesis',actual_prefix_steps=1048576,modes=['normalized_operand_exponents','unshifted_subnormal_exponent_minus14','unshifted_subnormal_exponent_minus15'],actual_prefix_mismatches_by_family=counts,best=best,recursive_prefix_mismatches=recursive_bad,recursive_endpoint_mismatches=end_bad,examples=examples,script_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),wall_seconds=time.monotonic()-started,general_model_proven=False)
with (B/'dot2-signed-zero-analysis-r1.json').open('x') as f:json.dump(record,f,indent=2);f.write('\n')
print(json.dumps({k:v for k,v in record.items() if k!='examples'},indent=2),flush=True)

